-- ClickHouse-specific syntax: FINAL, SAMPLE, PREWHERE, ARRAY JOIN, LIMIT BY, WITH FILL, lambdas, FORMAT, SETTINGS
SELECT * FROM users FINAL WHERE id = 1;
SELECT count() FROM users FINAL;
SELECT * FROM events SAMPLE 0.1;
SELECT count() * 10 FROM events SAMPLE 1 / 10;
SELECT * FROM events SAMPLE 10000 OFFSET 0.5;
SELECT * FROM events PREWHERE user_id = 5 WHERE ts > now() - INTERVAL 1 DAY;
SELECT * FROM events FINAL PREWHERE user_id = 5 WHERE name = 'click';
SELECT id, tag FROM t ARRAY JOIN tags AS tag;
SELECT id, tag FROM t LEFT ARRAY JOIN tags AS tag;
SELECT id, tag, idx FROM t ARRAY JOIN tags AS tag, arrayEnumerate(tags) AS idx;
SELECT n.k, n.v FROM t ARRAY JOIN n;
SELECT user_id, page FROM web_events ORDER BY ts DESC LIMIT 3 BY user_id;
SELECT user_id, page FROM web_events ORDER BY ts DESC LIMIT 1, 2 BY user_id;
SELECT user_id, page FROM web_events ORDER BY ts DESC LIMIT 2 BY user_id, page LIMIT 100;
SELECT n FROM numbers(10) ORDER BY n WITH FILL FROM 0 TO 20;
SELECT d, c FROM daily ORDER BY d WITH FILL FROM toDate('2024-01-01') TO toDate('2024-02-01') STEP 1;
SELECT d, c FROM daily ORDER BY d WITH FILL STEP INTERVAL 1 DAY;
SELECT d, c FROM daily ORDER BY d WITH FILL STEP toIntervalDay(1) INTERPOLATE (c AS c + 1);
SELECT arrayMap(x -> x * 2, [1, 2, 3]) AS doubled;
SELECT arrayFilter(x -> x > 1, arr) FROM t;
SELECT arrayMap((x, y) -> x + y, a, b) FROM t;
SELECT arrayExists(x -> x LIKE 'err%', tags) FROM t;
SELECT arrayFold((acc, x) -> acc + x, [1, 2, 3], toUInt64(0));
SELECT arraySort(x -> -x, arr), arrayReverseSort(arr), arrayDistinct(arr) FROM t;
SELECT arrayStringConcat(arrayMap(x -> toString(x), arr), ',') FROM t;
SELECT has(tags, 'a'), hasAll(tags, ['a', 'b']), length(tags), empty(tags), arrayElement(tags, 1), tags[1] FROM t;
SELECT [1, 2, 3][2], (1, 'a').1, tupleElement((1, 'a'), 2);
SELECT m['key'], mapKeys(m), mapValues(m), map('a', 1, 'b', 2) FROM t;
SELECT sumState(x), uniqState(user_id), quantileState(0.9)(x) FROM t;
SELECT sumMerge(s), uniqMerge(u), quantileMerge(0.9)(q) FROM daily_agg GROUP BY day;
SELECT sumIfState(x, x > 0) FROM t;
SELECT sumArray(arr), avgArray(arr), minMap(m) FROM t;
SELECT sumForEach(arr) FROM t;
SELECT count() FROM t SETTINGS max_threads = 4;
SELECT * FROM t LIMIT 10 SETTINGS max_execution_time = 10, max_memory_usage = 10000000000;
SELECT * FROM t FORMAT JSON;
SELECT * FROM t FORMAT JSONEachRow;
SELECT * FROM t LIMIT 5 FORMAT TabSeparated;
SELECT * FROM t SETTINGS max_threads = 2 FORMAT CSVWithNames;
SELECT id FROM t WHERE id GLOBAL IN (SELECT id FROM dist_t);
SELECT id FROM t WHERE id GLOBAL NOT IN (SELECT id FROM dist_t);
SELECT * FROM t WHERE (a, b) IN ((1, 2), (3, 4));
SELECT * FROM t WHERE id IN (SELECT id FROM s);
SELECT * FROM remote('host:9000', db.tbl) LIMIT 1;
SELECT * FROM cluster('my_cluster', default.events) LIMIT 1;
SELECT * FROM clusterAllReplicas('my_cluster', system.metrics) LIMIT 1;
SELECT * FROM url('https://example.com/data.csv', CSV, 'a UInt32, b String');
SELECT * FROM s3('https://bucket.s3.amazonaws.com/data/*.parquet', 'Parquet') LIMIT 10;
SELECT * FROM file('data.csv', 'CSVWithNames');
SELECT * FROM generateRandom('a UInt8, b String', 1, 10, 2) LIMIT 3;
SELECT cast(x AS String), CAST(x, 'UInt32'), x::UInt64, toInt32OrNull('12'), toFloat64OrZero('x'), accurateCastOrNull(x, 'UInt8') FROM t;
SELECT toDateTime('2024-01-01 00:00:00', 'UTC'), toTimeZone(now(), 'Asia/Kolkata'), now64(3), today(), yesterday();
SELECT parseDateTimeBestEffort('2024-01-01T10:00:00Z'), formatDateTime(now(), '%Y-%m-%d');
SELECT JSONExtractString(j, 'a'), JSONExtractInt(j, 'b', 'c'), JSONExtract(j, 'x', 'Array(UInt8)'), JSONHas(j, 'k'), simpleJSONExtractString(j, 'z') FROM t;
SELECT visitParamExtractString(j, 'a'), 1 FROM t;
SELECT extract(s, '(\\d+)'), match(s, '^a.*b$'), replaceRegexpAll(s, '[aeiou]', '_'), splitByChar(',', s), position(s, 'x'), lower(s), upper(s), trim(s), concat(a, b), substring(s, 1, 3) FROM t;
SELECT domain(url), path(url), protocol(url), extractURLParameter(url, 'q'), cutQueryString(url) FROM t;
SELECT cityHash64(s), sipHash64(s), MD5(s), SHA256(s), halfMD4(s), xxHash64(s) FROM t;
SELECT IPv4StringToNum('1.2.3.4'), IPv4NumToString(x), toIPv4('1.2.3.4'), toIPv6('::1'), isIPAddressInRange('1.2.3.4', '1.2.3.0/24');
SELECT bitAnd(a, b), bitShiftLeft(a, 2), intDiv(a, b), modulo(a, b), a <> b;
SELECT x IS NULL, x IS NOT NULL, ifNull(x, 0), nullIf(x, 0), isNull(x), assumeNotNull(x) FROM t;
SELECT s LIKE '%a%', s NOT LIKE 'b%', s ILIKE '%A%', s NOT ILIKE 'x%' FROM t;
SELECT * FROM t WHERE ts > now() - INTERVAL 1 HOUR AND s != '' OR x BETWEEN 1 AND 2;
SELECT x AS "quoted col", `back-tick` FROM `my-table`;
SELECT * EXCEPT (secret) FROM t;
SELECT * EXCEPT (a, b), COLUMNS('^x_') FROM t;
SELECT COLUMNS('a|b') APPLY (sum) FROM t;
SELECT * REPLACE (x + 1 AS x) FROM t;
SELECT 'it''s', 'back\\slash', 'tab\t', 0x1F, 1e3, 1.5e-3;
SELECT toDecimal64(1.5, 2), 100500::Decimal(10, 2), toUInt256(1), 123456789012345678901234567890::UInt128;
SELECT 1 FROM system.one;
SELECT name, engine FROM system.tables WHERE database = currentDatabase();
